using System.Diagnostics;
using System.Text;
using System.Text.RegularExpressions;

namespace Darklands.Core.Tests;

/// <summary>
/// The faithfulness registers (docs/faithfulness, generated by tools/faithfulness/registers.py from the
/// <c>// DIVERGENCE:</c>, <c>// BUG:</c>, <c>// UNCERTAIN:</c> and <c>// DORMANT:</c> comments in src/) stay honest:
/// every divergence and bug marker states a reason and names an original function that exists in the index,
/// every marker of the source is in the register, and the generated files are what the generator produces now
/// (like a golden file: regenerate with <c>python tools/faithfulness/registers.py</c>).
/// </summary>
public sealed class FaithfulnessRegisterTests(Xunit.Abstractions.ITestOutputHelper output)
{
    private static readonly string Root = FindRepositoryRoot();
    private static readonly string Docs = Path.Combine(Root, "docs", "faithfulness");

    [Fact]
    public void EveryDivergenceAndBugHasAReasonAndAnOriginalFunction()
    {
        var known = KnownOriginalFunctions();
        var problems = new List<string>();
        foreach (var file in new[] { "divergences.csv", "original_bugs.csv" })
        {
            foreach (var row in ReadCsv(Path.Combine(Docs, file)))
            {
                var where = $"{file} {row["id"]} ({row["file"]}:{row["line"]})";
                if (row["note"].Trim().Length < 12)
                {
                    problems.Add($"{where}: the reason is empty or too short: '{row["note"]}'");
                }
                var originals = row["original"].Replace("(+", "|(+", StringComparison.Ordinal).Split('|')[0]
                    .Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
                if (originals.Length == 0)
                {
                    problems.Add($"{where}: no original function (no // orig: comment resolves)");
                }
                foreach (var name in originals)
                {
                    if (!known.Contains(name))
                    {
                        problems.Add($"{where}: {name} is not in docs/source-map/original-functions.csv");
                    }
                }
            }
        }
        Assert.True(problems.Count == 0, string.Join(Environment.NewLine, problems));
    }

    /// <summary>The generator's scan agrees with a plain line scan of the source: no marker is missing from the registers.</summary>
    [Theory]
    [InlineData("DIVERGENCE", "divergences.csv")]
    [InlineData("BUG", "original_bugs.csv")]
    [InlineData("UNCERTAIN", "uncertain.csv")]
    [InlineData("DORMANT", "dormant.csv")]
    public void EveryMarkerOfTheSourceIsInTheRegister(string marker, string csv)
    {
        var line = new Regex($@"//+\s*{marker}\b", RegexOptions.Compiled);
        var inSource = Directory.GetFiles(Path.Combine(Root, "src"), "*.cs", SearchOption.AllDirectories)
            .Where(f => !f.Contains($"{Path.DirectorySeparatorChar}obj{Path.DirectorySeparatorChar}", StringComparison.Ordinal)
                && !f.Contains($"{Path.DirectorySeparatorChar}bin{Path.DirectorySeparatorChar}", StringComparison.Ordinal))
            .Sum(f => File.ReadLines(f).Count(l => line.IsMatch(l)));
        var inRegister = ReadCsv(Path.Combine(Docs, csv)).Count(r => r["form"] == "start");
        Assert.True(inSource == inRegister, $"{marker}: {inSource} markers in src/, {inRegister} in {csv}; regenerate the registers");
    }

    [Fact]
    public void EveryCoreDivergenceOfTheReviewListHasARecommendation()
    {
        var text = File.ReadAllText(Path.Combine(Docs, "DIVERGENCE_REVIEW.md"));
        Assert.DoesNotContain("NEEDS REVIEW", text, StringComparison.Ordinal);
    }

    [Fact]
    public void TheGeneratedRegistersAreUpToDate()
    {
        var script = Path.Combine(Root, "tools", "faithfulness", "registers.py");
        Assert.True(File.Exists(script), "tools/faithfulness/registers.py is missing");
        foreach (var python in new[] { Environment.GetEnvironmentVariable("DARKLANDS_PYTHON") ?? "", LocalPythonPath(), "python", "python3", "py" })
        {
            if (python.Length == 0 || (Path.IsPathRooted(python) && !File.Exists(python)))
            {
                continue;
            }
            ProcessStartInfo info = new(python, $"-I \"{script}\" --check")
            {
                WorkingDirectory = Root,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
            };
            info.Environment["PYTHONIOENCODING"] = "utf-8";
            Process? process;
            try
            {
                process = Process.Start(info);
            }
            catch (System.ComponentModel.Win32Exception)
            {
                continue;
            }
            using (process)
            {
                if (process is null)
                {
                    continue;
                }
                var output = process.StandardOutput.ReadToEnd() + process.StandardError.ReadToEnd();
                process.WaitForExit();
                Assert.True(process.ExitCode == 0, output);
                return;
            }
        }
        const string Message = "SKIPPED: no Python interpreter found (DARKLANDS_PYTHON, \"python\" in local/paths.json, python, python3, py); cannot regenerate-and-compare the faithfulness registers";
        output.WriteLine(Message);
        Assert.False(Environment.GetEnvironmentVariable("DARKLANDS_REQUIRE_PYTHON") == "1", Message);
    }

    /// <summary>The interpreter named under "python" in local/paths.json (git-ignored), or empty.</summary>
    private static string LocalPythonPath()
    {
        try
        {
            var file = Path.Combine(Root, "local", "paths.json");
            if (!File.Exists(file))
            {
                return "";
            }
            using var doc = System.Text.Json.JsonDocument.Parse(File.ReadAllText(file));
            return doc.RootElement.TryGetProperty("python", out var value) ? value.GetString() ?? "" : "";
        }
        catch (Exception e) when (e is System.Text.Json.JsonException or IOException or InvalidOperationException)
        {
            return "";
        }
    }

    private static HashSet<string> KnownOriginalFunctions() =>
        File.ReadLines(Path.Combine(Root, "docs", "source-map", "original-functions.csv")).Skip(1)
            .Select(l => l.Split(',')[0]).ToHashSet(StringComparer.Ordinal);

    /// <summary>A small RFC 4180 reader (quoted cells may hold commas, doubled quotes and line breaks).</summary>
    private static List<Dictionary<string, string>> ReadCsv(string path)
    {
        var text = File.ReadAllText(path, Encoding.UTF8).Replace("\r\n", "\n", StringComparison.Ordinal);
        var rows = new List<List<string>>();
        var row = new List<string>();
        var cell = new StringBuilder();
        var quoted = false;
        for (var i = 0; i < text.Length; i++)
        {
            var c = text[i];
            if (quoted)
            {
                if (c == '"' && i + 1 < text.Length && text[i + 1] == '"')
                {
                    cell.Append('"');
                    i++;
                }
                else if (c == '"')
                {
                    quoted = false;
                }
                else
                {
                    cell.Append(c);
                }
            }
            else if (c == '"')
            {
                quoted = true;
            }
            else if (c == ',')
            {
                row.Add(cell.ToString());
                cell.Clear();
            }
            else if (c == '\n')
            {
                row.Add(cell.ToString());
                cell.Clear();
                rows.Add(row);
                row = [];
            }
            else
            {
                cell.Append(c);
            }
        }
        if (cell.Length > 0 || row.Count > 0)
        {
            row.Add(cell.ToString());
            rows.Add(row);
        }
        var header = rows[0];
        return rows.Skip(1).Where(r => r.Count == header.Count)
            .Select(r => header.Zip(r).ToDictionary(p => p.First, p => p.Second, StringComparer.Ordinal)).ToList();
    }

    private static string FindRepositoryRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "Darklands.slnx")))
        {
            dir = dir.Parent;
        }
        return dir?.FullName ?? throw new InvalidOperationException("repository root not found");
    }
}
